package com.vitaflow.app.common

import retrofit2.Response
import java.io.IOException

sealed class Resource<T>(val data: T? = null, val message: String? = null) {
 class Success<T>(data: T) : Resource<T>(data)
 class Error<T>(message: String, data: T? = null) : Resource<T>(data, message)
 class Loading<T>(data: T? = null) : Resource<T>(data)

}
suspend fun<T> safeApiCall(apiCall: suspend () -> Response<T>): Resource<T>{
 return try {
 val res = apiCall.invoke()
 if(res.isSuccessful){
 Resource.Success(data = res.body()!!)
 }else{
 Resource.Error(message = res.errorBody().toString())
 }
 }catch (e: Exception){
 Resource.Error(e.message!!)
 }catch (e: IOException){
 Resource.Error(message = e.message!!)
 }
}
```"},{"role":"assistant","content":[{"type":"text","text":"You're absolutely correct! Looking at your `safeApiCall` function, it only returns `Resource.Success` or `Resource.Error` - it never returns `Resource.Loading`. The `Resource.Loading` branch in your when expression is indeed dead code that will never be executed.

