// In your repository:
override suspend fun getAllExercises(): Flow<Resource<List<Exercise>>> {
 return safeApiCallFlow { api.getAllExercises() }
 .map { res ->
 when (res) {
 is Resource.Success -> {
 Resource.Success(data = res.data?.data?.map { it.toExercise() } ?: emptyList())
 }
 is Resource.Error -> {
 Resource.Error(message = res.message ?: "Something went wrong")
 }
 is Resource.Loading -> {
 Resource.Loading()
 }
 }
 }
}
```

## ✅ **Option 2: Keep using the original but handle Loading in ViewModel**
In your ViewModel, manually emit Loading before calling the use case:

```kotlin
