 )
 },
 actions = {
 Icon(
 imageVector = Icons.Filled.Notifications,
 contentDescription = "Notifications"
 )
 }
 )
 },
 bottomBar = {
 BottomNavigationBar()
 },
 containerColor = Color.White
 ) { paddingValues ->
 Column(
 modifier = Modifier
 .fillMaxSize()
 .padding(paddingValues)
