 verticalArrangement = Arrangement.spacedBy(24.dp)
 ) {
 // Greeting Section
 Column(
 verticalArrangement = Arrangement.spacedBy(8.dp)
 ) {
 Text(
 text = "Hello,",
 fontSize = 24.sp,
 color = Color.Gray,
 fontWeight = FontWeight.Normal
 )
 Text(
 text = "User",
 fontSize = 32.sp,
 color = Color.Black,
