@Composable
fun Badge(
 text: String,
 backgroundColor: Color
) {
 Surface(
 shape = RoundedCornerShape(12.dp),
 color = backgroundColor
 ) {
 Text(
 text = text,
 modifier = Modifier.padding(horizontal = 12.dp, vertical = 6.dp),
 color = Color.White,
 fontSize = 12.sp,
 fontWeight = FontWeight.Medium
 )
 }
}

@Composable
fun WorkoutTypeCard(
 workout: WorkoutType
) {
 Card(
 modifier = Modifier
 .width(140.dp)
 .height(160.dp),
 shape = RoundedCornerShape(12.dp),
 colors = CardDefaults.cardColors(containerColor = Color.Transparent)
 ) {
 Box(
 modifier = Modifier.fillMaxSize()
 ) {
 // Background
 Box(
 modifier = Modifier
 .fillMaxSize()
 .background(Color.Gray)
 .background(
 Brush.verticalGradient(
 colors = listOf(
 Color.Transparent,
 Color.Black.copy(alpha = 0.7f)
 )
 )
 )
 )

 // Content
 Column(
 modifier = Modifier
 .fillMaxSize()
 .padding(16.dp),
 verticalArrangement = Arrangement.End
 ) {
 Text(
 text = workout.name,
 color = Color.White,
 fontSize = 18.sp,
 fontWeight = FontWeight.Bold
 )
 Text(
 text = "${workout.sessions} session",
 color = Color.White.copy(alpha = 0.8f),
 fontSize = 12.sp
 )
 }
 }
 }
}

@Composable
fun AdditionalTrainingItem(
 training: AdditionalTraining
) {
 Row(
 modifier = Modifier
 .fillMaxWidth()
 .padding(vertical = 8.dp),
 horizontalArrangement = Arrangement.spacedBy(12.dp),
 verticalAlignment = Alignment.CenterVertically
 ) {
 // Image
 Box(
 modifier = Modifier
 .size(60.dp)
 .clip(RoundedCornerShape(8.dp))
 .background(Color.Gray)
 )

 // Content
 Column(
 modifier = Modifier.weight(1f),
 verticalArrangement = Arrangement.spacedBy(4.dp)
 ) {
 Text(
 text = training.name,
 fontSize = 16.sp,
 color = Color.Black,
 fontWeight = FontWeight.Bold
 )

 Row(
 horizontalArrangement = Arrangement.spacedBy(16.dp)
 ) {
 Row(
 verticalAlignment = Alignment.CenterVertically,
 horizontalArrangement = Arrangement.spacedBy(4.dp)
 ) {
 Box(
 modifier = Modifier
 .size(8.dp)
 .clip(CircleShape)
 .background(Color.Green)
 )
 Text(
 text = "${training.calories} kcal",
 color = Color.Gray,
 fontSize = 12.sp
 )
 }

 Row(
 verticalAlignment = Alignment.CenterVertically,
 horizontalArrangement = Arrangement.spacedBy(4.dp)
 ) {
 Box(
 modifier = Modifier
 .size(8.dp)
 .clip(CircleShape)
 .background(Color.Green)
 )
 Text(
 text = training.duration,
 color = Color.Gray,
 fontSize = 12.sp
 )
 }
 }

 Text(
 text = training.level,
 color = Color.Gray,
 fontSize = 12.sp
 )
 }
 }
}

@Composable
fun BottomNavigationBar() {
 NavigationBar(
 containerColor = Color.White,
 modifier = Modifier.height(80.dp)
 ) {
 bottomNavItems.forEach { item ->
 NavigationBarItem(
 icon = {
 Icon(
 item.icon,
 contentDescription = item.title,
 modifier = Modifier.size(24.dp)
 )
 },
 label = {
 Text(
 text = item.title,
 fontSize = 12.sp
 )
 },
 selected = item.title == "Home",
 onClick = { /* Handle navigation */ },
 colors = NavigationBarItemDefaults.colors(
 selectedIconColor = Color(0xFF1A1A1A),
 unselectedIconColor = Color.Gray,
 selectedTextColor = Color(0xFF1A1A1A),
 unselectedTextColor = Color.Gray,
 indicatorColor = Color.Transparent
 )
 )
 }
 }
}

// Data classes
data class WorkoutType(
 val name: String,
 val sessions: Int
)

data class AdditionalTraining(
 val name: String,
 val calories: Int,
 val duration: String,
 val level: String
)

data class BottomNavItem(
 val title: String,
 val icon: ImageVector
)

// Sample data
val workoutTypes = listOf(
 WorkoutType("Hiit", 12),
 WorkoutType("Amrap", 15),
 WorkoutType("For time", 8)
)

val additionalTraining = listOf(
 AdditionalTraining("Deep Amrap Burner", 125, "15min", "Beginner • Full body"),
 AdditionalTraining("Deep Butt Sculp", 180, "20min", "Intermediate • Lower body")
)

val bottomNavItems = listOf(
 BottomNavItem("Home", Icons.Default.Home),
 BottomNavItem("Search", Icons.Default.Search),
 BottomNavItem("Article", Icons.Default.Menu),
 BottomNavItem("Profile", Icons.Default.Person)
)

