 setKeepOnScreenCondition{
 showSplashScreen
 }
 setOnExitAnimationListener{ screen ->
 val zoomX = ObjectAnimator.ofFloat(
 screen.iconView,
 View.SCALE_X,
 0.5f,
 0f
 )
 val zoomY = ObjectAnimator.ofFloat(
 screen.iconView,
 View.SCALE_Y,
 0.5f,
 0f
 )
 zoomX.duration = 500
 zoomY.duration = 500
 zoomX.interpolator = OvershootInterpolator()
 zoomY.interpolator = OvershootInterpolator()
 zoomX.doOnEnd {
 screen.remove()
 }
 zoomX.doOnEnd {
 screen.remove()
 }
 zoomX.start()
 zoomY.start()
 }
 }
 super.onCreate(savedInstanceState)
 enableEdgeToEdge()
 setContent {
 VitaFlowTheme {
 val navController = rememberNavController()
 val currentRoute by navController.currentBackStackEntryAsState()

 // Check if current route should show bottom bar
 val shouldShowBottomBar = currentRoute?.destination?.route?.let { route ->
 route != Routes.SIGNINSCREEN &&
 route != Routes.SIGNUPSCREEN &&
 !route.startsWith(Routes.WORKOUTSCREEN)
 } ?: false

 Scaffold(
 bottomBar = {
 if (shouldShowBottomBar) {
 BottomNavigationBar(navController = navController)
 }
 }
 ) { paddingValues ->
 NavHost(
 navController = navController,
 startDestination = Routes.SIGNINSCREEN,
 modifier = if (shouldShowBottomBar) {
 Modifier.padding(bottom = paddingValues.calculateBottomPadding())
 } else {
 Modifier
 },
 enterTransition = {
 slideIntoContainer(
 towards = AnimatedContentTransitionScope.SlideDirection.Left,
 animationSpec = tween(300)
 ) + fadeIn(animationSpec = tween(300))
 },
 exitTransition = {
 slideOutOfContainer(
 towards = AnimatedContentTransitionScope.SlideDirection.Left,
 animationSpec = tween(300)
 ) + fadeOut(animationSpec = tween(300))
 },
 popEnterTransition = {
 slideIntoContainer(
 towards = AnimatedContentTransitionScope.SlideDirection.Right,
 animationSpec = tween(300)
 ) + fadeIn(animationSpec = tween(300))
 },
 popExitTransition = {
 slideOutOfContainer(
 towards = AnimatedContentTransitionScope.SlideDirection.Right,
 animationSpec = tween(300)
 ) + fadeOut(animationSpec = tween(300))
 }) {
 composable(Routes.SIGNINSCREEN) {
 SignInScreen(navController)
 }
 composable(Routes.SIGNUPSCREEN) {
 SignUpScreen(navController)
 }
 composable(Routes.HOMESCREEN) {
 HomeScreen(navController)
 }
 composable(Routes.WORKOUTSCREEN + "/{exerciseId}") {
 ExerciseDetailScreen(navController = navController)
 }
 }
 }
 }
 }
 CoroutineScope(Dispatchers.IO).launch {
 delay(3000)
 showSplashScreen = false
 }
 }
