@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun NutritionScreen(
 navController: NavController,
 viewModel: NutritionViewModel = hiltViewModel()
) {
 val uiState = viewModel.state.collectAsStateWithLifecycle()
 val scrollBehavior = TopAppBarDefaults.pinnedScrollBehavior(rememberTopAppBarState())

 Scaffold(
 topBar = {
 TopAppBar(
 colors = TopAppBarDefaults.topAppBarColors(
 containerColor = Color.White,
 titleContentColor = Color.Black,
 actionIconContentColor = Color.Black
 ),
 title = {
 Column {
 Text(
 text = "Nutrition",
 fontSize = 20.sp,
 fontWeight = FontWeight.Bold,
 color = Color.Black
 )
 Text(
 text = SimpleDateFormat("EEEE, MMM dd", Locale.getDefault()).format(Date()),
 fontSize = 12.sp,
 color = Color.Gray,
 fontWeight = FontWeight.Normal
 )
 }
 },
 actions = {
 IconButton(onClick = { /* TODO: Search functionality */ }) {
 Icon(
 imageVector = Icons.Default.Search,
 contentDescription = "Search Food",
 tint = Color.Black
 )
 }
 IconButton(onClick = { /* TODO: Settings */ }) {
 Icon(
 imageVector = Icons.Default.Settings,
 contentDescription = "Settings",
 tint = Color.Black
 )
 }
 },
 scrollBehavior = scrollBehavior
 )
 },
 containerColor = Color(0xFFF8F9FA)
 ) { paddingValues ->
 LazyColumn(
 modifier = Modifier
 .fillMaxSize()
 .padding(paddingValues),
 contentPadding = PaddingValues(16.dp),
 verticalArrangement = Arrangement.spacedBy(16.dp)
 ) {
 // Calorie Overview Card
 item {
 CalorieOverviewCard(
 totalCalories = uiState.value.totalCalories,
 targetCalories = uiState.value.targetCalories,
 consumedCalories = uiState.value.consumedCalories,
 burnedCalories = uiState.value.burnedCalories
 )
 }

 // Macronutrients Card
 item {
 MacronutrientsCard(
 carbs = uiState.value.carbs,
 protein = uiState.value.protein,
 fat = uiState.value.fat
 )
 }

 // Quick Add Buttons
 item {
 QuickAddSection()
 }

 // Meals Section
 item {
 MealsSection(
 meals = uiState.value.meals,
 onAddMeal = { mealType ->
 // TODO: Navigate to food search/add screen
 }
 )
 }

 // Water Intake
 item {
 WaterIntakeCard(
 currentIntake = uiState.value.waterIntake,
 targetIntake = uiState.value.targetWaterIntake,
 onAddWater = { amount ->
 viewModel.addWater(amount)
 }
 )
 }

 // Recent Foods
 item {
 RecentFoodsSection(
 recentFoods = uiState.value.recentFoods,
 onFoodClick = { food ->
 // TODO: Add food to current meal
 }
 )
 }

 // Nutrition Tips
 item {
 NutritionTipsCard()
 }
 }
 }
}

@Composable
fun CalorieOverviewCard(
 totalCalories: Int,
 targetCalories: Int,
 consumedCalories: Int,
 burnedCalories: Int
) {
 val remainingCalories = targetCalories - consumedCalories + burnedCalories
 val progress = (consumedCalories.toFloat() / targetCalories.toFloat()).coerceIn(0f, 1f)

 val animatedProgress by animateFloatAsState(
 targetValue = progress,
 animationSpec = spring(
 dampingRatio = Spring.DampingRatioMediumBouncy,
 stiffness = Spring.StiffnessLow
 ),
 label = "progress"
 )

 Card(
 modifier = Modifier.fillMaxWidth(),
 shape = RoundedCornerShape(16.dp),
 colors = CardDefaults.cardColors(containerColor = Color.White),
 elevation = CardDefaults.cardElevation(defaultElevation = 4.dp)
 ) {
 Column(
 modifier = Modifier.padding(20.dp),
 horizontalAlignment = Alignment.CenterHorizontally
 ) {
 Text(
 text = "Daily Calories",
 fontSize = 18.sp,
 fontWeight = FontWeight.Bold,
 color = Color.Black
 )

 Spacer(modifier = Modifier.height(16.dp))

 // Circular Progress
 Box(
 contentAlignment = Alignment.Center,
 modifier = Modifier.size(160.dp)
 ) {
 CircularProgressIndicator(
 progress = { 1f },
 modifier = Modifier.fillMaxSize(),
 color = Color.Gray.copy(alpha = 0.2f),
 strokeWidth = 12.dp,
 trackColor = Color.Transparent
 )
 CircularProgressIndicator(
 progress = { animatedProgress },
 modifier = Modifier.fillMaxSize(),
 color = if (remainingCalories >= 0) Color(0xFF4CAF50) else Color(0xFFFF5722),
 strokeWidth = 12.dp,
 trackColor = Color.Transparent
 )
 Column(
 horizontalAlignment = Alignment.CenterHorizontally
 ) {
 Text(
 text = "$remainingCalories",
 fontSize = 28.sp,
 fontWeight = FontWeight.Bold,
 color = Color.Black
 )
 Text(
 text = if (remainingCalories >= 0) "remaining" else "over",
 fontSize = 14.sp,
 color = Color.Gray
 )
 }
 }

 Spacer(modifier = Modifier.height(20.dp))

 Row(
 modifier = Modifier.fillMaxWidth(),
 horizontalArrangement = Arrangement.SpaceEvenly
 ) {
 CalorieInfo(
 label = "Target",
 value = targetCalories,
 color = Color(0xFF2196F3)
 )
 CalorieInfo(
 label = "Food",
 value = consumedCalories,
 color = Color(0xFF4CAF50)
 )
 CalorieInfo(
 label = "Exercise",
 value = burnedCalories,
 color = Color(0xFFFF9800)
 )
 }
 }
 }
}

@Composable
fun CalorieInfo(
 label: String,
 value: Int,
 color: Color
) {
 Column(
 horizontalAlignment = Alignment.CenterHorizontally
 ) {
 Text(
 text = "$value",
 fontSize = 16.sp,
 fontWeight = FontWeight.Bold,
 color = color
 )
 Text(
 text = label,
 fontSize = 12.sp,
 color = Color.Gray
 )
 }
}

@Composable
fun MacronutrientsCard(
 carbs: MacroNutrient,
 protein: MacroNutrient,
