@Composable
fun QuickAddButton(
 icon: ImageVector,
 label: String,
 color: Color,
 onClick: () -> Unit
) {
 var isPressed by remember { mutableStateOf(false) }
 val scale by animateFloatAsState(
 targetValue = if (isPressed) 0.95f else 1f,
 animationSpec = spring(dampingRatio = Spring.DampingRatioMediumBouncy),
 label = "button_scale"
 )

 Column(
 horizontalAlignment = Alignment.CenterHorizontally,
 modifier = Modifier
 .scale(scale)
 .clickable {
 isPressed = true
 onClick()
 }
 ) {
 Box(
 modifier = Modifier
 .size(60.dp)
 .background(
 color.copy(alpha = 0.1f),
 CircleShape
 ),
 contentAlignment = Alignment.Center
 ) {
 Icon(
 imageVector = icon,
 contentDescription = label,
 tint = color,
 modifier = Modifier.size(28.dp)
 )
 }

 Spacer(modifier = Modifier.height(8.dp))

 Text(
 text = label,
 fontSize = 12.sp,
 color = Color.Gray,
 textAlign = TextAlign.Center
 )
 }
}

@Composable
fun MealsSection(
 meals: List<Meal>,
 onAddMeal: (String) -> Unit
) {
 Column {
 Text(
 text = "Today's Meals",
 fontSize = 18.sp,
 fontWeight = FontWeight.Bold,
 color = Color.Black,
 modifier = Modifier.padding(bottom = 16.dp)
 )

 Column(
 verticalArrangement = Arrangement.spacedBy(12.dp)
 ) {
 mealTypes.forEach { mealType ->
 val meal = meals.find { it.type == mealType.type }
 MealCard(
 mealType = mealType,
 meal = meal,
 onAddClick = { onAddMeal(mealType.type) }
 )
 }
 }
 }
}

@Composable
fun MealCard(
 mealType: MealType,
 meal: Meal?,
 onAddClick: () -> Unit
) {
 Card(
 modifier = Modifier.fillMaxWidth(),
 shape = RoundedCornerShape(12.dp),
 colors = CardDefaults.cardColors(containerColor = Color.White),
 elevation = CardDefaults.cardElevation(defaultElevation = 2.dp)
 ) {
 Row(
 modifier = Modifier
 .fillMaxWidth()
 .padding(16.dp),
 horizontalArrangement = Arrangement.SpaceBetween,
 verticalAlignment = Alignment.CenterVertically
 ) {
 Row(
 verticalAlignment = Alignment.CenterVertically,
 horizontalArrangement = Arrangement.spacedBy(12.dp)
 ) {
 Icon(
 imageVector = mealType.icon,
 contentDescription = mealType.name,
 tint = mealType.color,
 modifier = Modifier.size(24.dp)
 )

 Column {
 Text(
 text = mealType.name,
 fontSize = 16.sp,
 fontWeight = FontWeight.Medium,
 color = Color.Black
 )
 Text(
 text = if (meal != null) "${meal.calories} cal" else "0 cal",
 fontSize = 12.sp,
 color = Color.Gray
 )
 }
 }

 IconButton(onClick = onAddClick) {
 Icon(
 imageVector = Icons.Default.Add,
 contentDescription = "Add ${mealType.name}",
 tint = Color.Gray
 )
 }
 }
 }
}

@Composable
fun WaterIntakeCard(
 currentIntake: Int,
 targetIntake: Int,
 onAddWater: (Int) -> Unit
) {
 val progress = (currentIntake.toFloat() / targetIntake.toFloat()).coerceIn(0f, 1f)

 Card(
 modifier = Modifier.fillMaxWidth(),
 shape = RoundedCornerShape(16.dp),
 colors = CardDefaults.cardColors(containerColor = Color.White),
 elevation = CardDefaults.cardElevation(defaultElevation = 4.dp)
 ) {
 Column(
 modifier = Modifier.padding(20.dp)
 ) {
 Row(
 modifier = Modifier.fillMaxWidth(),
 horizontalArrangement = Arrangement.SpaceBetween,
 verticalAlignment = Alignment.CenterVertically
 ) {
 Row(
 verticalAlignment = Alignment.CenterVertically,
 horizontalArrangement = Arrangement.spacedBy(8.dp)
 ) {
 Icon(
 imageVector = Icons.Default.WaterDrop,
 contentDescription = "Water",
 tint = Color(0xFF2196F3),
 modifier = Modifier.size(24.dp)
 )
 Text(
 text = "Water Intake",
 fontSize = 18.sp,
 fontWeight = FontWeight.Bold,
 color = Color.Black
 )
 }

 Text(
 text = "$currentIntake / $targetIntake ml",
 fontSize = 14.sp,
 color = Color.Gray
 )
 }

 Spacer(modifier = Modifier.height(16.dp))

 // Water Progress Bar
 Box(
 modifier = Modifier
 .fillMaxWidth()
 .height(12.dp)
 .background(
 Color.Gray.copy(alpha = 0.2f),
 RoundedCornerShape(6.dp)
 )
 ) {
 Box(
 modifier = Modifier
 .fillMaxWidth(progress)
 .fillMaxHeight()
 .background(
 Brush.horizontalGradient(
 colors = listOf(
 Color(0xFF2196F3),
 Color(0xFF03DAC6)
 )
 ),
 RoundedCornerShape(6.dp)
 )
 )
 }

 Spacer(modifier = Modifier.height(16.dp))

 // Water Add Buttons
 Row(
 modifier = Modifier.fillMaxWidth(),
 horizontalArrangement = Arrangement.SpaceEvenly
 ) {
 listOf(250, 500, 750).forEach { amount ->
 OutlinedButton(
 onClick = { onAddWater(amount) },
 shape = RoundedCornerShape(20.dp),
 colors = ButtonDefaults.outlinedButtonColors(
 contentColor = Color(0xFF2196F3)
 ),
 border = ButtonDefaults.outlinedButtonBorder.copy(
 brush = Brush.linearGradient(
 colors = listOf(Color(0xFF2196F3), Color(0xFF03DAC6))
 )
 )
 ) {
 Text(
 text = "+${amount}ml",
 fontSize = 12.sp
 )
 }
 }
 }
 }
 }
}

@Composable
fun RecentFoodsSection(
 recentFoods: List<Food>,
 onFoodClick: (Food) -> Unit
) {
 if (recentFoods.isNotEmpty()) {
 Column {
 Text(
 text = "Recent Foods",
 fontSize = 18.sp,
 fontWeight = FontWeight.Bold,
 color = Color.Black,
 modifier = Modifier.padding(bottom = 16.dp)
 )

 LazyRow(
 horizontalArrangement = Arrangement.spacedBy(12.dp)
 ) {
 items(recentFoods) { food ->
 FoodCard(
 food = food,
 onClick = { onFoodClick(food) }
 )
 }
 }
 }
 }
}

@Composable
fun FoodCard(
 food: Food,
 onClick: () -> Unit
) {
 Card(
 modifier = Modifier
 .width(140.dp)
 .clickable { onClick() },
 shape = RoundedCornerShape(12.dp),
 colors = CardDefaults.cardColors(containerColor = Color.White),
 elevation = CardDefaults.cardElevation(defaultElevation = 2.dp)
 ) {
 Column(
 modifier = Modifier.padding(12.dp)
 ) {
 AsyncImage(
 model = ImageRequest.Builder(LocalContext.current)
 .data(food.imageUrl)
 .crossfade(true)
 .build(),
 contentDescription = food.name,
 modifier = Modifier
 .fillMaxWidth()
 .height(80.dp)
 .clip(RoundedCornerShape(8.dp)),
 contentScale = ContentScale.Crop
 )

 Spacer(modifier = Modifier.height(8.dp))

 Text(
 text = food.name,
 fontSize = 14.sp,
 fontWeight = FontWeight.Medium,
 color = Color.Black,
 maxLines = 2,
 overflow = TextOverflow.Ellipsis
 )

 Spacer(modifier = Modifier.height(4.dp))

 Text(
 text = "${food.calories} cal",
 fontSize = 12.sp,
 color = Color.Gray
 )
 }
 }
}

