// Data classes
data class MacroNutrient(
 val current: Int,
 val target: Int
)

data class Meal(
 val type: String,
 val foods: List<Food>,
 val calories: Int
)

data class Food(
 val id: String,
 val name: String,
 val calories: Int,
 val carbs: Int,
 val protein: Int,
 val fat: Int,
 val imageUrl: String
)

data class MealType(
 val type: String,
 val name: String,
 val icon: ImageVector,
 val color: Color
)

data class QuickAddItem(
 val label: String,
 val icon: ImageVector,
 val color: Color
)

// Sample data
val mealTypes = listOf(
 MealType("breakfast", "Breakfast", Icons.Default.WbSunny, Color(0xFFFF9800)),
 MealType("lunch", "Lunch", Icons.Default.LunchDining, Color(0xFF4CAF50)),
 MealType("dinner", "Dinner", Icons.Default.DinnerDining, Color(0xFF9C27B0)),
 MealType("snacks", "Snacks", Icons.Default.Cookie, Color(0xFF2196F3))
)

val quickAddItems = listOf(
 QuickAddItem("Scan", Icons.Default.QrCodeScanner, Color(0xFF4CAF50)),
 QuickAddItem("Photo", Icons.Default.PhotoCamera, Color(0xFF2196F3)),
 QuickAddItem("Recipe", Icons.Default.MenuBook, Color(0xFFFF9800)),
 QuickAddItem("Quick Cal", Icons.Default.Add, Color(0xFF9C27B0))
)

