 color = Color.Gray,
 fontSize = 12.sp
 )
 }
 }

 Spacer(modifier = Modifier.height(4.dp))

 Text(
 text = training.level,
 color = Color.Gray,
 fontSize = 12.sp
 )
 }
 }
}

