import androidx.navigation.NavController
import androidx.navigation.compose.rememberNavController
import coil3.compose.AsyncImage
import coil3.request.ImageRequest
import coil3.request.crossfade
import com.vitaflow.app.domain.models.Exercise

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun ExerciseDetailScreen(
 navController: NavController,
 viewModel: ExerciseDetailViewModel = hiltViewModel()
) {
 var isFavorite by remember { mutableStateOf(false) }
 val scrollBehavior = TopAppBarDefaults.pinnedScrollBehavior(rememberTopAppBarState())
 val state = viewModel.state.collectAsStateWithLifecycle().value

 Scaffold(
 topBar = {
 TopAppBar(
 title = {
 Text(
 text = state.exercise?.name ?: "",
 fontWeight = FontWeight.Medium,
 maxLines = 1,
 overflow = TextOverflow.Ellipsis
 )
 },
 navigationIcon = {
 IconButton(onClick = { navController.popBackStack() }) {
 Icon(
 Icons.Default.ArrowBack,
 contentDescription = "Back"
 )
 }
 },
 actions = {
 IconButton(onClick = { isFavorite = !isFavorite }) {
 Icon(
 if (isFavorite) Icons.Default.Favorite else Icons.Default.FavoriteBorder,
 contentDescription = "Favorite",
 tint = if (isFavorite) Color.Red else Color.Gray
 )
 }
 IconButton(onClick = { /* Handle share */ }) {
 Icon(
 Icons.Default.Share,
 contentDescription = "Share"
 )
 }
 },
 colors = TopAppBarDefaults.topAppBarColors(
 containerColor = Color.Transparent
 ),
 scrollBehavior = scrollBehavior
 )
 },
 containerColor = Color(0xFFF8F9FA)
 ) { paddingValues ->
 when {
 state.isLoading -> {
 ExerciseDetailShimmer(paddingValues = paddingValues)
 }

 state.error.isNotEmpty() -> {
 Box(
 modifier = Modifier
 .fillMaxSize()
 .padding(paddingValues),
 contentAlignment = Alignment.Center
 ) {
 Column(
 horizontalAlignment = Alignment.CenterHorizontally,
 verticalArrangement = Arrangement.spacedBy(16.dp)
 ) {
 Text(
 text = "Error: ${state.error}",
 color = Color.Red,
 textAlign = TextAlign.Center,
 fontSize = 16.sp
 )
 Button(
 onClick = { navController.popBackStack() }
 ) {
 Text("Go Back")
 }
 }
 }
 }

 state.exercise != null -> {
 val exercise = state.exercise
 LazyColumn(
 modifier = Modifier
 .fillMaxSize()
 .padding(paddingValues),
 contentPadding = PaddingValues(16.dp),
 verticalArrangement = Arrangement.spacedBy(20.dp)
 ) {
 // Exercise Image/GIF Section
 item {
 Card(
 modifier = Modifier
 .fillMaxWidth()
 .height(280.dp),
 shape = RoundedCornerShape(20.dp),
 colors = CardDefaults.cardColors(containerColor = Color.White),
 elevation = CardDefaults.cardElevation(defaultElevation = 4.dp)
 ) {
 Box(
 modifier = Modifier.fillMaxSize()
 ) {
 AsyncImage(
 model = ImageRequest.Builder(LocalContext.current)
 .data(exercise.gifUrl)
 .crossfade(true)
 .build(),
 contentDescription = exercise.name,
 modifier = Modifier
 .fillMaxSize()
 .clip(RoundedCornerShape(20.dp)),
 contentScale = ContentScale.Crop,
 onError = { error ->
 println("Error loading exercise GIF: ${error.result.throwable}")
 }
 )

 // Play button overlay
 Box(
 modifier = Modifier
 .align(Alignment.Center)
 .size(64.dp)
 .clip(CircleShape)
 .background(Color.Black.copy(alpha = 0.7f)),
 contentAlignment = Alignment.Center
 ) {
 Icon(
 Icons.Default.PlayArrow,
 contentDescription = "Play",
 tint = Color.White,
 modifier = Modifier.size(32.dp)
 )
 }

 // Rating badge
 Surface(
 modifier = Modifier
 .align(Alignment.TopEnd)
 .padding(16.dp),
 shape = RoundedCornerShape(20.dp),
 color = Color.Black.copy(alpha = 0.7f)
 ) {
 Row(
 modifier = Modifier.padding(
 horizontal = 12.dp,
 vertical = 6.dp
 ),
 verticalAlignment = Alignment.CenterVertically,
 horizontalArrangement = Arrangement.spacedBy(4.dp)
 ) {
 Icon(
 Icons.Default.Star,
 contentDescription = null,
 tint = Color.Yellow,
 modifier = Modifier.size(16.dp)
 )
 Text(
 text = "4.8",
 color = Color.White,
 fontSize = 12.sp,
 fontWeight = FontWeight.Bold
 )
 }
 }
 }
 }
 }

 // Exercise Info Section
 item {
 Card(
 modifier = Modifier.fillMaxWidth(),
 shape = RoundedCornerShape(16.dp),
 colors = CardDefaults.cardColors(containerColor = Color.White),
 elevation = CardDefaults.cardElevation(defaultElevation = 2.dp)
 ) {
 Column(
 modifier = Modifier.padding(20.dp),
 verticalArrangement = Arrangement.spacedBy(16.dp)
 ) {
 Text(
 text = exercise.name,
 fontSize = 24.sp,
 fontWeight = FontWeight.Bold,
 color = Color.Black
 )

 // Stats Row
 Row(
 modifier = Modifier.fillMaxWidth(),
 horizontalArrangement = Arrangement.SpaceEvenly
 ) {
 StatItem(
 label = "Duration",
 value = "15 min",
 icon = android.R.drawable.ic_menu_recent_history
 )
 StatItem(
 label = "Calories",
 value = "120 kcal",
 icon = android.R.drawable.ic_menu_info_details
 )
 StatItem(
 label = "Level",
 value = "Intermediate",
 icon = android.R.drawable.ic_menu_sort_by_size
 )
 }
 }
 }
 }

 // Target Muscles Section
 item {
 SectionCard(
 title = "Target Muscles",
 subtitle = "Primary muscle groups"
 ) {
 LazyRow(
 horizontalArrangement = Arrangement.spacedBy(8.dp)
 ) {
 items(exercise.targetMuscles) { muscle ->
 MuscleChip(
 text = muscle,
 isPrimary = true
 )
 }
 }
 }
 }

 // Secondary Muscles Section
 if (exercise.secondaryMuscles.isNotEmpty()) {
 item {
 SectionCard(
 title = "Secondary Muscles",
 subtitle = "Supporting muscle groups"
 ) {
 LazyRow(
 horizontalArrangement = Arrangement.spacedBy(8.dp)
 ) {
 items(exercise.secondaryMuscles) { muscle ->
 MuscleChip(
 text = muscle,
 isPrimary = false
 )
 }
 }
 }
 }
 }

 // Equipment Section
 if (exercise.equipments.isNotEmpty()) {
 item {
 SectionCard(
 title = "Equipment Needed",
 subtitle = "Required equipment"
 ) {
 LazyRow(
 horizontalArrangement = Arrangement.spacedBy(8.dp)
 ) {
 items(state.exercise.equipments) { equipment ->
 EquipmentChip(text = equipment)
 }
 }
 }
 }
 }

 // Instructions Section
 item {
 SectionCard(
 title = "Instructions",
 subtitle = "Step by step guide"
 ) {
 Column(
 verticalArrangement = Arrangement.spacedBy(12.dp)
 ) {
 exercise.instructions.forEachIndexed { index, instruction ->
 InstructionItem(
 stepNumber = index + 1,
 instruction = instruction
 )
 }
 }
 }
 }

 // Action Button
 item {
 Button(
 onClick = { /* Handle start workout */ },
 modifier = Modifier
 .fillMaxWidth()
 .height(56.dp),
 shape = RoundedCornerShape(16.dp),
 colors = ButtonDefaults.buttonColors(
 containerColor = Color.Black
 )
 ) {
 Row(
 verticalAlignment = Alignment.CenterVertically,
 horizontalArrangement = Arrangement.spacedBy(8.dp)
 ) {
 Icon(
 Icons.Default.PlayArrow,
 contentDescription = null,
 tint = Color.White
 )
 Text(
 text = "Start Workout",
 fontSize = 16.sp,
 fontWeight = FontWeight.Bold,
 color = Color.White
 )
 }
 }
 }
 }
 }
 }
 }
}

@Composable
fun SectionCard(
 title: String,
 subtitle: String,
 content: @Composable () -> Unit
) {
 Card(
 modifier = Modifier.fillMaxWidth(),
 shape = RoundedCornerShape(16.dp),
 colors = CardDefaults.cardColors(containerColor = Color.White),
 elevation = CardDefaults.cardElevation(defaultElevation = 2.dp)
 ) {
 Column(
 modifier = Modifier.padding(20.dp),
 verticalArrangement = Arrangement.spacedBy(12.dp)
 ) {
 Column(
 verticalArrangement = Arrangement.spacedBy(4.dp)
 ) {
 Text(
 text = title,
 fontSize = 18.sp,
 fontWeight = FontWeight.Bold,
 color = Color.Black
 )
 Text(
 text = subtitle,
 fontSize = 14.sp,
 color = Color.Gray
 )
 }
 content()
 }
 }
}

@Composable
fun StatItem(
 label: String,
 value: String,
 icon: Int
) {
 Column(
 horizontalAlignment = Alignment.CenterHorizontally,
 verticalArrangement = Arrangement.spacedBy(8.dp)
 ) {
 Surface(
 modifier = Modifier.size(48.dp),
 shape = CircleShape,
 color = Color(0xFFF8F9FA)
 ) {
 Box(
 contentAlignment = Alignment.Center
 ) {
 Icon(
 painter = painterResource(id = icon),
 contentDescription = null,
 tint = Color.Black,
 modifier = Modifier.size(24.dp)
 )
 }
 }
 Column(
 horizontalAlignment = Alignment.CenterHorizontally
 ) {
 Text(
 text = value,
 fontSize = 16.sp,
 fontWeight = FontWeight.Bold,
 color = Color.Black
 )
 Text(
 text = label,
 fontSize = 12.sp,
 color = Color.Gray
 )
 }
 }
}

@Composable
fun MuscleChip(
 text: String,
 isPrimary: Boolean
) {
 Surface(
 shape = RoundedCornerShape(20.dp),
 color = if (isPrimary) Color.Black else Color(0xFFE0E0E0)
 ) {
 Text(
 text = text.replaceFirstChar { it.uppercase() },
 modifier = Modifier.padding(horizontal = 16.dp, vertical = 8.dp),
 color = if (isPrimary) Color.White else Color.Black,
 fontSize = 14.sp,
 fontWeight = FontWeight.Medium
 )
 }
}

@Composable
fun EquipmentChip(text: String) {
 Surface(
 shape = RoundedCornerShape(20.dp),
 color = Color(0xFF2196F3).copy(alpha = 0.1f),
 modifier = Modifier.border(
 1.dp,
 Color(0xFF2196F3).copy(alpha = 0.3f),
 RoundedCornerShape(20.dp)
 )
 ) {
 Text(
 text = text.replaceFirstChar { it.uppercase() },
 modifier = Modifier.padding(horizontal = 16.dp, vertical = 8.dp),
 color = Color(0xFF2196F3),
 fontSize = 14.sp,
 fontWeight = FontWeight.Medium
 )
 }
}

@Composable
fun InstructionItem(
 stepNumber: Int,
 instruction: String
) {
 Row(
 modifier = Modifier.fillMaxWidth(),
 horizontalArrangement = Arrangement.spacedBy(12.dp)
 ) {
 Surface(
 modifier = Modifier.size(32.dp),
 shape = CircleShape,
 color = Color.Black
 ) {
 Box(
 contentAlignment = Alignment.Center
 ) {
 Text(
 text = stepNumber.toString(),
 color = Color.White,
 fontSize = 14.sp,
 fontWeight = FontWeight.Bold
 )
 }
 }

 Text(
 text = instruction,
 modifier = Modifier.weight(1f),
 fontSize = 14.sp,
 color = Color.Black,
 lineHeight = 20.sp
 )
 }
}

@Composable
fun ExerciseDetailShimmer(paddingValues: PaddingValues) {
 val shimmerColors = listOf(
 Color.Gray.copy(alpha = 0.9f),
 Color.Gray.copy(alpha = 0.2f),
 Color.Gray.copy(alpha = 0.9f)
 )

 val transition = rememberInfiniteTransition(label = "shimmer")
 val translationAnimation = transition.animateFloat(
 initialValue = 0f,
 targetValue = 1000f,
 animationSpec = infiniteRepeatable(
 animation = tween(1000, easing = LinearEasing),
 repeatMode = RepeatMode.Restart
 ),
 label = "shimmer_translation"
 )

 fun shimmerBrush(): Brush {
 return Brush.linearGradient(
 colors = shimmerColors,
 start = Offset(10f, 10f),
 end = Offset(translationAnimation.value, translationAnimation.value)
 )
 }

 LazyColumn(
 modifier = Modifier
 .fillMaxSize()
 .padding(paddingValues),
 contentPadding = PaddingValues(16.dp),
 verticalArrangement = Arrangement.spacedBy(20.dp)
 ) {
 // Exercise Image/GIF Section Shimmer
