 exerciseId = "1",
 name = "Push Up",
 targetMuscles = listOf("chest", "triceps"),
 secondaryMuscles = listOf("shoulders", "core"),
 bodyParts = listOf("upper body"),
 equipments = listOf("body weight"),
 gifUrl = "https://example.com/pushup.gif",
 instructions = listOf(
