 color = Color.White,
 shadowElevation = 12.dp,
 tonalElevation = 8.dp
 ) {
 NavigationBar(
 containerColor = Color.White,
 contentColor = Color.Black,
 modifier = Modifier
 .fillMaxWidth()
 .height(88.dp)
 .padding(horizontal = 16.dp, vertical = 8.dp),
 tonalElevation = 0.dp
 ) {
 bottomNavItems.forEachIndexed { index, item ->
 val isSelected = when (item.title) {
 "Home" -> currentDestination == Routes.HOMESCREEN
 "Nutrition" -> currentDestination?.startsWith("nutrition") == true
 "Workout" -> currentDestination?.startsWith("workout_list") == true
 "Articles" -> currentDestination?.startsWith("articles") == true
 "Profile" -> currentDestination?.startsWith("profile") == true
 else -> false
 }

 NavigationBarItem(
 icon = {
 Box(
 modifier = Modifier
 .size(48.dp)
 .background(
 color = if (isSelected) Color.Black else Color.Transparent,
 shape = RoundedCornerShape(16.dp)
 ),
 contentAlignment = Alignment.Center
 ) {
 Icon(
 imageVector = item.icon,
 contentDescription = item.title,
 modifier = Modifier.size(24.dp),
 tint = if (isSelected) Color.White else Color.Gray
 )
 }
 },
 label = {
 Text(
 text = item.title,
 fontSize = 12.sp,
 fontWeight = if (isSelected) FontWeight.Bold else FontWeight.Medium,
 color = if (isSelected) Color.Black else Color.Gray,
 maxLines = 1,
 overflow = TextOverflow.Ellipsis
 )
 },
 selected = isSelected,
 onClick = {
 // Handle navigation based on item
 when (item.title) {
 "Home" -> {
 if (currentDestination != Routes.HOMESCREEN) {
 navController.navigate(Routes.HOMESCREEN) {
 popUpTo(navController.graph.findStartDestination().id) {
 saveState = true
 }
 launchSingleTop = true
 restoreState = true
 }
 }
 }

