package com.vitaflow.app.presentation.ui

import android.animation.ObjectAnimator
import android.os.Bundle
import android.view.View
import android.view.animation.OvershootInterpolator
import androidx.activity.ComponentActivity
import androidx.activity.compose.setContent
import androidx.activity.enableEdgeToEdge
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.foundation.layout.padding
import androidx.compose.foundation.text.BasicSecureTextField
import androidx.compose.material3.Scaffold
import androidx.compose.material3.Text
import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import androidx.compose.ui.tooling.preview.Preview
import androidx.core.animation.doOnEnd
import androidx.core.splashscreen.SplashScreen.Companion.installSplashScreen
import androidx.navigation.NavHost
import androidx.navigation.compose.NavHost
import androidx.navigation.compose.composable
import androidx.navigation.compose.rememberNavController
import com.vitaflow.app.common.Routes
import com.vitaflow.app.presentation.ui.auth.signin.SignInScreen
import com.vitaflow.app.presentation.ui.theme.VitaFlowTheme
import dagger.hilt.android.AndroidEntryPoint
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.delay
import kotlinx.coroutines.launch

@AndroidEntryPoint
class MainActivity : ComponentActivity() {
 var showSplashScreen = true
 override fun onCreate(savedInstanceState: Bundle?) {
 installSplashScreen().apply {
 setKeepOnScreenCondition{
 showSplashScreen
 }
 setOnExitAnimationListener{ screen ->
 val zoomX = ObjectAnimator.ofFloat(
 screen.iconView,
 View.SCALE_X,
 0.5f,
 0f
 )
 val zoomY = ObjectAnimator.ofFloat(
 screen.iconView,
 View.SCALE_Y,
 0.5f,
 0f
 )
 zoomX.duration = 500
 zoomY.duration = 500
 zoomX.interpolator = OvershootInterpolator()
 zoomY.interpolator = OvershootInterpolator()
 zoomX.doOnEnd {
 screen.remove()
 }
 zoomX.doOnEnd {
 screen.remove()
 }
 zoomX.start()
 zoomY.start()
 }
 }
 super.onCreate(savedInstanceState)
 enableEdgeToEdge()
 setContent {
 VitaFlowTheme {
 val navController = rememberNavController()
 NavHost(
 navController = navController,
 startDestination = Routes.SIGNINSCREEN){
 composable(Routes.SIGNINSCREEN) {
 SignInScreen()
 }
 }
 }
 }
 CoroutineScope(Dispatchers.IO).launch {
 delay(3000)
 showSplashScreen = false
 }
 }
}
