@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun HomeScreen(
 navController: NavController,
 viewModel: HomeViewModel = hiltViewModel()
) {
 val scrollBehavior = TopAppBarDefaults.pinnedScrollBehavior(rememberTopAppBarState())
 val uiState = viewModel.state.collectAsStateWithLifecycle()

 // Random anime character image for featured workout
 val randomAnimeCharacter by remember {
 mutableStateOf(animeCharacterImages.random())
 }

 Scaffold(
 topBar = {
 CenterAlignedTopAppBar(
 colors = TopAppBarDefaults.centerAlignedTopAppBarColors(
 containerColor = Color.Transparent,
 titleContentColor = Color.Black
 ),
 title = {
 Text(
 text = "Vita Flow",
 overflow = TextOverflow.Ellipsis,
 fontWeight = FontWeight.Medium
 )
 },
 actions = {
 Icon(
 imageVector = Icons.Filled.Notifications,
 contentDescription = "Notifications"
 )
 }
 )
 },
 bottomBar = {
 BottomNavigationBar()
 },
 containerColor = Color(0xFFF8F9FA)
 ) { paddingValues ->
 LazyColumn(
 modifier = Modifier
 .fillMaxSize()
 .padding(paddingValues),
 contentPadding = PaddingValues(16.dp)
 ) {
 item {
 // Header Section
 Row(
 modifier = Modifier.fillMaxWidth(),
 horizontalArrangement = Arrangement.SpaceBetween,
 verticalAlignment = Alignment.Top
 ) {
 Column {
 Text(
 text = "Hello, User!",
 fontSize = 16.sp,
 color = Color.Gray,
 fontWeight = FontWeight.Normal
 )
 Text(
 text = "Stay Fit & Healthy",
 fontSize = 24.sp,
 color = Color.Black,
 fontWeight = FontWeight.Bold
 )
 }
 }
 }

 item {
 Spacer(modifier = Modifier.height(24.dp))
 }

 item {
 // Trending Workouts Section
 Column {
 Row(
 verticalAlignment = Alignment.CenterVertically,
 horizontalArrangement = Arrangement.spacedBy(8.dp)
 ) {
 Text(
 text = "Trending Workouts",
 fontSize = 20.sp,
 color = Color.Black,
 fontWeight = FontWeight.Bold
 )
 Text(
 text = "",
 fontSize = 20.sp
 )
 }

 Spacer(modifier = Modifier.height(16.dp))

 // Featured Workout Card with Anime Character Background
 Card(
 modifier = Modifier
 .fillMaxWidth()
 .height(200.dp),
 shape = RoundedCornerShape(16.dp),
 colors = CardDefaults.cardColors(containerColor = Color.Transparent)
 ) {
 Box(
 modifier = Modifier.fillMaxSize()
 ) {
 // Anime Character Background Image
 AsyncImage(
 model = ImageRequest.Builder(LocalContext.current)
 .data(randomAnimeCharacter.imageUrl)
 .crossfade(true)
 .build(),
 contentDescription = randomAnimeCharacter.name,
 modifier = Modifier.fillMaxSize(),
 contentScale = ContentScale.Crop,
 onError = { error ->
 println("Error loading anime character image: ${error.result.throwable}")
 }
 )

 // Gradient overlay for better text readability
 Box(
 modifier = Modifier
 .fillMaxSize()
 .background(
 Brush.verticalGradient(
 colors = listOf(
 Color.Transparent,
 Color.Black.copy(alpha = 0.7f)
 )
 )
 )
 )

 // Content
 Column(
 modifier = Modifier
 .fillMaxSize()
 .padding(20.dp),
 verticalArrangement = Arrangement.SpaceBetween
 ) {
 // Top badges
 Row(
 horizontalArrangement = Arrangement.spacedBy(8.dp)
 ) {
 Badge(
 text = "Beginner",
 backgroundColor = Color.White.copy(alpha = 0.3f)
 )
 Badge(
 text = "Full body",
 backgroundColor = Color.White.copy(alpha = 0.3f)
 )
 Badge(
 text = randomAnimeCharacter.anime,
 backgroundColor = Color(0xFF6C63FF).copy(alpha = 0.8f)
 )
 }

 // Bottom content
 Row(
 modifier = Modifier.fillMaxWidth(),
 horizontalArrangement = Arrangement.SpaceBetween,
 verticalAlignment = Alignment.Bottom
 ) {
 Column {
 Text(
 text = "${randomAnimeCharacter.name}'s Workout",
 fontSize = 24.sp,
 color = Color.White,
 fontWeight = FontWeight.Bold
 )

 Spacer(modifier = Modifier.height(8.dp))

 Row(
 horizontalArrangement = Arrangement.spacedBy(16.dp)
 ) {
 Row(
 verticalAlignment = Alignment.CenterVertically,
 horizontalArrangement = Arrangement.spacedBy(4.dp)
 ) {
 Icon(
 painter = painterResource(id = android.R.drawable.ic_menu_info_details),
 contentDescription = null,
 tint = Color.White,
 modifier = Modifier.size(16.dp)
 )
 Text(
 text = "350 kcal",
 color = Color.White,
 fontSize = 14.sp
 )
 }

 Row(
 verticalAlignment = Alignment.CenterVertically,
 horizontalArrangement = Arrangement.spacedBy(4.dp)
 ) {
 Icon(
 painter = painterResource(id = android.R.drawable.ic_menu_recent_history),
 contentDescription = null,
 tint = Color.White,
 modifier = Modifier.size(16.dp)
 )
 Text(
 text = "1h 25min",
 color = Color.White,
 fontSize = 14.sp
 )
 }
 }
 }

 // Rating
 Row(
 verticalAlignment = Alignment.CenterVertically,
 horizontalArrangement = Arrangement.spacedBy(4.dp)
 ) {
 Icon(
 Icons.Default.Star,
 contentDescription = null,
