 fontWeight = FontWeight.Medium
 )
 }
}

@Composable
fun WorkoutTypeCard(
 exercise: Exercise,
 onClick: () -> Unit
) {
 val context = LocalContext.current

 Card(
 modifier = Modifier
 .width(140.dp)
 .clickable { onClick() }
 .height(160.dp),
 shape = RoundedCornerShape(12.dp),
 colors = CardDefaults.cardColors(containerColor = Color.White),
 elevation = CardDefaults.cardElevation(defaultElevation = 2.dp)
 ) {
 Box(
 modifier = Modifier.fillMaxSize()
 ) {
 // Background Image with fallback
 if (exercise.gifUrl.isNotEmpty()) {
 AsyncImage(
 model = ImageRequest.Builder(context)
 .data(exercise.gifUrl)
 .crossfade(true)
 .build(),
 contentDescription = exercise.name,
 modifier = Modifier.fillMaxSize(),
 contentScale = ContentScale.Crop,
 onSuccess = {
 println("Successfully loaded: ${exercise.gifUrl}")
 },
 onError = { error ->
 println("Error loading exercise image: ${error.result.throwable}")
 println("Failed URL: ${exercise.gifUrl}")
 },
 onLoading = {
 println("Loading: ${exercise.gifUrl}")
 }
 )
 } else {
 // Fallback background if no image
 Box(
 modifier = Modifier
 .fillMaxSize()
 .background(
 Brush.linearGradient(
 colors = listOf(
 Color(0xFF6C63FF),
 Color(0xFF4CAF50)
 )
 )
 )
 )
 }

 // Gradient overlay for better text readability
 Box(
 modifier = Modifier
 .fillMaxSize()
 .background(
 Brush.verticalGradient(
 colors = listOf(
 Color.Transparent,
 Color.Black.copy(alpha = 0.7f)
 ),
 startY = 0f,
 endY = Float.POSITIVE_INFINITY
 )
 )
 )

 // Content
 Column(
 modifier = Modifier
 .fillMaxSize()
 .padding(16.dp),
 verticalArrangement = Arrangement.Bottom
 ) {
 Text(
 text = exercise.name.take(25), // Limit text length
 color = Color.White,
 fontSize = 16.sp,
 fontWeight = FontWeight.Bold,
 maxLines = 2,
 overflow = TextOverflow.Ellipsis
 )
 Spacer(modifier = Modifier.height(4.dp))
 Text(
 text = "Workout",
 color = Color.White.copy(alpha = 0.8f),
 fontSize = 12.sp
 )
 }
 }
 }
}

@Composable
fun AdditionalTrainingItem(
 training: AdditionalTraining
) {
 Row(
 modifier = Modifier
 .fillMaxWidth()
 .padding(vertical = 8.dp),
 horizontalArrangement = Arrangement.spacedBy(12.dp),
 verticalAlignment = Alignment.CenterVertically
 ) {
 // Image
 Box(
 modifier = Modifier
 .size(60.dp)
 .clip(RoundedCornerShape(8.dp))
 .background(Color.Gray)
 )

 // Content
 Column(
 modifier = Modifier.weight(1f)
 ) {
 Text(
 text = training.name,
 fontSize = 16.sp,
 color = Color.Black,
 fontWeight = FontWeight.Bold
 )

 Spacer(modifier = Modifier.height(4.dp))

 Row(
 horizontalArrangement = Arrangement.spacedBy(16.dp)
 ) {
 Row(
 verticalAlignment = Alignment.CenterVertically,
 horizontalArrangement = Arrangement.spacedBy(4.dp)
 ) {
 Box(
 modifier = Modifier
 .size(8.dp)
 .clip(CircleShape)
 .background(Color.Green)
 )
 Text(
 text = "${training.calories} kcal",
 color = Color.Gray,
 fontSize = 12.sp
 )
 }

 Row(
 verticalAlignment = Alignment.CenterVertically,
 horizontalArrangement = Arrangement.spacedBy(4.dp)
 ) {
 Box(
 modifier = Modifier
 .size(8.dp)
 .clip(CircleShape)
 .background(Color.Green)
 )
 Text(
 text = training.duration,
 color = Color.Gray,
 fontSize = 12.sp
 )
 }
 }

 Spacer(modifier = Modifier.height(4.dp))

 Text(
 text = training.level,
 color = Color.Gray,
 fontSize = 12.sp
 )
 }
 }
}

@Composable
fun BottomNavigationBar() {
 var selectedIndex by remember { mutableStateOf(0) }

 Surface(
 modifier = Modifier.fillMaxWidth(),
 color = Color.White,
 shadowElevation = 12.dp,
 tonalElevation = 8.dp
 ) {
 NavigationBar(
 containerColor = Color.White,
 contentColor = Color.Black,
 modifier = Modifier
 .fillMaxWidth()
 .height(88.dp)
 .padding(horizontal = 16.dp, vertical = 8.dp),
 tonalElevation = 0.dp
 ) {
 bottomNavItems.forEachIndexed { index, item ->
 val isSelected = index == selectedIndex

 NavigationBarItem(
 icon = {
 Box(
 modifier = Modifier
 .size(48.dp)
 .background(
 color = if (isSelected) Color.Black else Color.Transparent,
 shape = RoundedCornerShape(16.dp)
 ),
 contentAlignment = Alignment.Center
 ) {
 Icon(
 imageVector = item.icon,
 contentDescription = item.title,
 modifier = Modifier.size(24.dp),
 tint = if (isSelected) Color.White else Color.Gray
 )
 }
 },
 label = {
 Text(
 text = item.title,
 fontSize = 12.sp,
 fontWeight = if (isSelected) FontWeight.Bold else FontWeight.Medium,
 color = if (isSelected) Color.Black else Color.Gray,
 maxLines = 1,
 overflow = TextOverflow.Ellipsis
 )
 },
 selected = isSelected,
 onClick = {
 selectedIndex = index
 // Handle navigation based on item
 when (item.title) {
 "Home" -> { /* Already on home */
 }

 "Search" -> { /* Navigate to search */
 }

 "Workout" -> { /* Navigate to workout */
 }

 "Articles" -> { /* Navigate to articles */
 }

 "Profile" -> { /* Navigate to profile */
 }
 }
 },
 colors = NavigationBarItemDefaults.colors(
 selectedIconColor = Color.Transparent,
 unselectedIconColor = Color.Transparent,
 selectedTextColor = Color.Black,
 unselectedTextColor = Color.Gray,
 indicatorColor = Color.Transparent,
 disabledIconColor = Color.Gray,
 disabledTextColor = Color.Gray
 ),
 modifier = Modifier.padding(horizontal = 2.dp)
 )
 }
 }
 }
}

